pub fn highest(config: &SpiConfig) -> u8 {
    return std::cmp::max(
        std::cmp::max(config.clk, config.cs.unwrap_or(0u8)),
        std::cmp::max(config.mosi.unwrap_or(0u8), config.miso.unwrap_or(0u8)),
    );
}

pub fn validate(config: &SpiConfig) -> Option<String> {
    if (config.mode > 3u8) {
        return Some(format!(
            "SPI mode {} does not exist; modes are 0 to 3",
            config.mode
        ));
    }
    if ((config.word_bits < 1u8) || (config.word_bits > 8u8)) {
        return Some(format!(
            "{} bits per word; 1 to 8 are supported",
            config.word_bits
        ));
    }
    if let Some(mosi) = config.mosi {
    } else {
        let Some(miso) = config.miso else {
            return Some(String::from("neither MOSI nor MISO is connected"));
        };
    }
    let mut seen: ChannelMask = ChannelMask::of([]);
    for line in [Some(config.clk), config.cs, config.mosi, config.miso] {
        let Some(line_2) = line else {
            continue;
        };
        if (line_2 >= MAX_CHANNELS) {
            return Some(format!(
                "channel {} is out of range; channels are 0 to {}",
                line_2,
                Int::wsub(MAX_CHANNELS, 1u8)
            ));
        }
        if seen.has(line_2) {
            return Some(format!("channel {} is used for two lines", line_2));
        }
        seen = seen.with(line_2);
    }
    return None;
}

